let randSeed=92741;function rand(){randSeed=(Math.imul(1664525,randSeed)+1013904223)>>>0;return randSeed/4294967296;}
function noiseTexture(kind){const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=kind==='bark'?'#4a5043':'#343e2c';ctx.fillRect(0,0,256,256);for(let i=0;i<6000;i++){const v=Math.floor(rand()*40);ctx.fillStyle=kind==='bark'?`rgba(${v+15},${v+20},${v+12},.5)`:`rgba(${v+20},${v+27},${v+9},.5)`;ctx.fillRect(rand()*256,rand()*256,kind==='bark'?rand()*3+1:rand()*8+1,kind==='bark'?rand()*80+2:rand()*5+1);}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(kind==='bark'?2:35,kind==='bark'?2:35);t.colorSpace=THREE.SRGBColorSpace;return t;}
function addObstacle(x,z,r,kind='structure'){const o={x,z,r,kind};obstacles.push(o);const k=Math.floor(x/4)+','+Math.floor(z/4);if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(o);}
function collision(x,z,r=.42){if(Math.abs(x)>44||Math.abs(z)>44)return true;const gx=Math.floor(x/4),gz=Math.floor(z/4);for(let i=-1;i<=1;i++)for(let j=-1;j<=1;j++){const list=buckets.get((gx+i)+','+(gz+j));if(list)for(const o of list)if((x-o.x)**2+(z-o.z)**2<(o.r+r)**2)return true;}return false;}
function moveEntity(obj,dx,dz,r=.42){if(!collision(obj.x+dx,obj.z,r))obj.x+=dx;if(!collision(obj.x,obj.z+dz,r))obj.z+=dz;}
function material(color,extra={}){return new THREE.MeshStandardMaterial({color,roughness:.95,...extra});}
function box(w,h,d,mat,x,y,z,parent=scene){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);parent.add(m);return m;}
function pole(radius,height,mat,x,z,parent=scene){const m=new THREE.Mesh(new THREE.CylinderGeometry(radius*.8,radius,height,7),mat);m.position.set(x,height/2,z);parent.add(m);return m;}
function treeInstances(){
 const bark=material(0x89917e,{map:noiseTexture('bark')});
 const trunks=new THREE.InstancedMesh(new THREE.CylinderGeometry(.55,.9,1,6),bark,420);
 const branches=new THREE.InstancedMesh(new THREE.CylinderGeometry(.04,.14,1,5),bark,1260);
 const foliage=new THREE.InstancedMesh(new THREE.ConeGeometry(1,1,7),material(0x24392a),840);
 const rocks=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,0),material(0x505747),65);
 trunks.name='forest-trunks';branches.name='forest-branches';foliage.name='forest-canopy';rocks.name='forest-pebbles';
 let count=0,bc=0,fc=0;
 const placedTrees=[];
 const spots=[[-23,-18],[-23,-21],[23,-22],[-25,12],[26,13],[0,30],[0,35]];
 const openRoute=(x,z)=>Math.abs(x)<4||Math.abs(z)<3||spots.some(p=>Math.hypot(x-p[0],z-p[1])<6);
 for(let n=0;n<2600&&count<420;n++){
  const x=(rand()-.5)*100,z=(rand()-.5)*100;
  if(openRoute(x,z)||Math.hypot(x,z+1)<8||collision(x,z,.8)&&Math.abs(x)<44&&Math.abs(z)<44||placedTrees.some(t=>Math.hypot(x-t.x,z-t.z)<2.5))continue;
  const h=9+rand()*12,r=.28+rand()*.4;
  // Upright trunks: visual centers and collision circles coincide at walking height.
  temp.position.set(x,h/2,z);temp.rotation.set(0,rand()*Math.PI,0);temp.scale.set(r,h,r);temp.updateMatrix();
  trunks.setMatrixAt(count++,temp.matrix);placedTrees.push({x,z,r});
  if(Math.abs(x)<44&&Math.abs(z)<44)addObstacle(x,z,Math.max(.22,r*.62),'trunk');
  // Branch bottoms stay above 5m; nothing protrudes at the player's eye level.
  for(let b=0;b<3;b++){
   temp.position.set(x,Math.max(7,h*(.65+b*.1)),z);
   temp.rotation.set((rand()-.5)*1.4,rand()*6.28,(rand()-.5)*1.4);
   temp.scale.set(1,2+rand()*2,1);temp.updateMatrix();branches.setMatrixAt(bc++,temp.matrix);
  }
  for(let f=0;f<2;f++){
   const crownHeight=3.5+rand()*2,crownBottom=Math.max(6,h*.62)+f*2;
   temp.position.set(x,crownBottom+crownHeight/2,z);temp.rotation.set(0,rand()*6.28,0);
   temp.scale.set(2+rand()*1.2,crownHeight,2+rand()*1.2);temp.updateMatrix();foliage.setMatrixAt(fc++,temp.matrix);
  }
 }
 trunks.count=count;branches.count=bc;foliage.count=fc;scene.add(trunks,branches,foliage);
 // Pebbles are scenery, not invisible ankle-height collision traps.
 let rc=0;
 for(let i=0;i<65;i++){
  const x=(rand()-.5)*86,z=(rand()-.5)*86;if(openRoute(x,z)||collision(x,z,.5))continue;
  const s=.15+rand()*.22;temp.position.set(x,.035,z);temp.rotation.set(0,rand()*6,0);
  temp.scale.set(s*1.4,s*.28,s);temp.updateMatrix();rocks.setMatrixAt(rc++,temp.matrix);
 }
 rocks.count=rc;scene.add(rocks);
 // Short, flat blades replace the old solid, waist-high triangular grass cones.
 const blades=new THREE.BufferGeometry();blades.setAttribute('position',new THREE.Float32BufferAttribute([
  -.035,0,0,.035,0,0,.055,.24,.015,
  -.08,0,.015,-.025,0,.015,-.12,.17,.04,
  .02,0,-.035,.02,0,.025,.08,.19,-.07
 ],3));blades.computeVertexNormals();
 const grass=new THREE.InstancedMesh(blades,material(0x34452b,{side:THREE.DoubleSide}),450);grass.name='forest-grass';
 let gc=0;
 for(let i=0;i<450;i++){
  const x=(rand()-.5)*95,z=(rand()-.5)*95;if(openRoute(x,z)||collision(x,z,.5))continue;
  temp.position.set(x,.005,z);temp.rotation.set(0,rand()*6,0);temp.scale.setScalar(.7+rand()*.45);
  temp.updateMatrix();grass.setMatrixAt(gc++,temp.matrix);
 }
 grass.count=gc;scene.add(grass);
}
function makeTorii(x,z,scale=1){const group=new THREE.Group();group.position.set(x,0,z);group.scale.setScalar(scale);scene.add(group);const red=material(0x713528),black=material(0x1d241d);for(const xx of [-3,3]){pole(.22,5,red,xx,0,group);box(.55,.7,.55,black,xx,.35,0,group);if(scale>.9)addObstacle(x+xx,z,.35);}box(7.3,.35,.45,red,0,4.3,0,group);box(8.2,.35,.65,black,0,5.2,0,group);box(7.5,.28,.45,red,0,4.9,0,group);box(.22,.7,.25,red,0,4.6,0,group);return group;}
