 box(9,.3,9,dark,cx,4,cz);for(let x=-3;x<=3;x+=1)box(.06,3.8,.05,dark,cx+x,1.9,cz-3.85);box(3,.8,1,wood,cx,1.1,cz-1);lantern(cx+5,cz+4);
 makeTorii(23,-25,.6);lantern(20,-21);
 // Water reservoir.
 const tank=new THREE.Mesh(new THREE.CylinderGeometry(2.3,2.3,3,14),metal);tank.position.set(-27,1.5,12);scene.add(tank);addObstacle(-27,12,2.4);for(let h=.3;h<3;h+=.5){const ring=new THREE.Mesh(new THREE.TorusGeometry(2.32,.045,4,20),dark);ring.rotation.x=Math.PI/2;ring.position.set(-27,h,12);scene.add(ring);}
 // Lumber yard.
