 const trunks=scene.getObjectByName('forest-trunks'),m=new THREE.Matrix4(),p=new THREE.Vector3(),q=new THREE.Quaternion(),s=new THREE.Vector3();for(let i=0;i<trunks.count;i++){trunks.getMatrixAt(i,m);m.decompose(p,q,s);this.positions.push({x:p.x,z:p.z,matrix:new THREE.Matrix4().compose(new THREE.Vector3(p.x,0,p.z),q,new THREE.Vector3(s.x*.9/1.35,s.y/50,s.z*.9/1.35)),variant:i%3});}
 for(const name of ['forest-trunks','forest-branches','forest-canopy']){const o=scene.getObjectByName(name);scene.remove(o);o.geometry.dispose();}
 for(let variant=0;variant<3;variant++)for(let level=0;level<3;level++){const pair=[];for(const kind of ['branches','leaves']){const mesh=new THREE.InstancedMesh(this.decode(NATURE_TREES[variant][level][kind]),kind==='branches'?bark:leaves,this.positions.length);mesh.count=0;mesh.frustumCulled=false;mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);mesh.name=`cedar-${variant}-${level}-${kind}`;scene.add(mesh);pair.push(mesh);}this.groups.push({variant,level,pair});}
 ground.material.dispose();ground.material=soil;ground.receiveShadow=true;
 const surfaces=new Map([[0x525449,wood],[0x657477,metal],[0x606354,stone],[0x72776b,stone]]);scene.traverse(o=>{if(!o.isMesh||Array.isArray(o.material))return;const replacement=surfaces.get(o.material.color?.getHex());if(replacement)o.material=replacement;});
 const grass=scene.getObjectByName('forest-grass');grass.geometry.dispose();const tuft=[-.025,0,0,.025,0,0,.008,.22,.01,-.02,0,-.018,.02,0,.018,-.012,.18,.03,0,0,-.026,0,0,.026,.018,.2,-.006,-.02,0,.02,.02,0,-.02,.026,.17,.012];grass.geometry=new THREE.BufferGeometry();grass.geometry.setAttribute('position',new THREE.Float32BufferAttribute(tuft,3));grass.geometry.computeVertexNormals();grass.material=new THREE.MeshStandardMaterial({side:THREE.DoubleSide,roughness:1,color:0x7e9273});
 const rocks=scene.getObjectByName('forest-pebbles');rocks.geometry.dispose();rocks.geometry=new THREE.IcosahedronGeometry(1,2);const a=rocks.geometry.attributes.position;for(let i=0;i<a.count;i++){const x=a.getX(i),y=a.getY(i),z=a.getZ(i),k=1+.12*Math.sin(x*7+z*4)*Math.cos(y*9);a.setXYZ(i,x*k,y*k,z*k);}rocks.geometry.computeVertexNormals();rocks.material=stone;
 flash.castShadow=!touchDevice&&settings.quality!=='low';renderer.shadowMap.enabled=!touchDevice&&settings.quality!=='low';renderer.shadowMap.type=THREE.PCFSoftShadowMap;flash.shadow.mapSize.set(512,512);flash.shadow.bias=-.001;flash.shadow.normalBias=.035;flash.angle=.48;flash.penumbra=.8;
