let naturalForest=null;
const natureInit=init;
init=async function(){await natureInit();if(!ready)return;ready=false;$('start').disabled=true;try{naturalForest=new ForestEnvironment();await naturalForest.load();ready=true;$('start').disabled=false;$('load-message').textContent='NIGHT FOREST · OFFLINE READY';}catch(e){show('fatal');$('fatal-detail').textContent='森林素材の読み込みに失敗しました。 '+e.message;}};
function updateMovePad(dx,dy){const length=Math.hypot(dx,dy),s=Math.min(length,40)/(length||1);input.mx=dx*s/40;input.my=dy*s/40;runHeld=runHeld?length>58:length>=72;const visual=Math.min(length,76)/(length||1);$('stick').style.transform=`translate(${dx*visual}px,${dy*visual}px)`;$('joystick').classList.toggle('sprinting',runHeld);}
// The interaction pointer never releases the movement or camera pointer.
$('interaction').addEventListener('pointerdown',e=>{if(state!=='playing')return;e.preventDefault();e.stopPropagation();interact();});

const NEW_DEFAULT_FACE="assets/1141972f976b8389.png";
/* Seven-part gameplay foundation. External shrine/cave asset integration pending. */
class ProximityStatic {
 constructor(){
  this.canvas=$('enemy-static');this.ctx=this.canvas.getContext('2d',{alpha:true});
  this.w=touchDevice?160:256;this.h=touchDevice?90:144;this.canvas.width=this.w;this.canvas.height=this.h;
  this.data=this.ctx.createImageData(this.w,this.h);this.next=0;this.burst=0;this.lastDanger=0;
 }
 update(danger){
  const visible=state==='playing'&&!settings.gentle&&danger>.015;
  if(!visible){this.clear();return;}
  danger=clamp(danger,0,1);
  const d=danger*danger;
  // 不規則な受信障害のように、強さは距離に比例しつつ常に揺らす。
  if(Math.random()<.012+d*.07)this.burst=.045+d*.11;
  this.burst=Math.max(0,this.burst-.016);
  const pulse=.72+Math.random()*.28+this.burst*2.4;
  this.canvas.style.opacity=String(Math.min(.48,(.025+danger*.15+d*.16)*pulse));
  const jitter=(Math.random()-.5)*(1.2+d*7)+(this.burst?((Math.random()-.5)*12):0);
  const jy=(Math.random()-.5)*(d*2.4);
  this.canvas.style.transform=`translate(${jitter}px,${jy}px) scale(1.015)`;
  this.canvas.style.filter=`contrast(${1.12+d*.8}) brightness(${.92-d*.14})`;
  if(elapsed<this.next)return;
  const staticMin=touchDevice?.045:.028,staticBase=touchDevice?.12:.10;this.next=elapsed+Math.max(staticMin,staticBase-danger*.055-Math.random()*.018);

  const a=this.data.data,w=this.w,h=this.h;
  const bandY=(Math.random()*h)|0,bandH=2+((Math.random()*(3+d*16))|0);
  const tearY=(Math.random()*h)|0,tearH=this.burst?4+((Math.random()*20)|0):0;
  for(let y=0;y<h;y++){
   const scan=(y&1)?-17:7;
   const inBand=Math.abs(y-bandY)<bandH;
   const inTear=tearH&&Math.abs(y-tearY)<tearH;
   for(let x=0;x<w;x++){
    const i=(y*w+x)*4;
    // 細粒ノイズ + 横方向に相関した筋。完全な白黒乱数より映像信号らしくする。
    let v=118+(Math.random()-.5)*(115+danger*105)+scan;
    if(inBand)v+=45+(Math.random()-.5)*95;
    if(inTear)v+=70+(Math.random()-.5)*150;
    if(Math.random()<.003+d*.018)v=Math.random()<.5?12:245;
    v=Math.max(0,Math.min(255,v));
    const chroma=(Math.random()-.5)*(8+d*26);
    a[i]=Math.max(0,Math.min(255,v+chroma));
    a[i+1]=v;
    a[i+2]=Math.max(0,Math.min(255,v-chroma));
    let alpha=18+danger*24+Math.random()*(24+d*42);
    if(inBand)alpha+=35+d*35;
    if(inTear)alpha+=75;
    a[i+3]=Math.min(210,alpha);
   }
  }
  this.ctx.putImageData(this.data,0,0);
  // ランダムな水平同期ズレを数本だけ追加。至近距離ほど長く・強くなる。
  const bands=1+((danger*4)|0)+(this.burst?2:0);
  for(let n=0;n<bands;n++){
   const y=(Math.random()*h)|0,bh=1+((Math.random()*(2+d*9))|0);
   const dx=((Math.random()-.5)*(5+d*30))|0;
   try{this.ctx.drawImage(this.canvas,0,y,w,bh,dx,y,w,bh);}catch(e){}
  }
  // ごく短い黒いドロップアウト。毎フレームは出さず、予測不能にする。
  if(Math.random()<.025+d*.11){
   const y=(Math.random()*h)|0,bh=1+((Math.random()*(1+d*7))|0);
   this.ctx.fillStyle=`rgba(0,0,0,${.18+d*.42})`;this.ctx.fillRect(0,y,w,bh);
  }
  this.lastDanger=danger;
 }
 clear(){this.canvas.style.opacity='0';this.canvas.style.transform='translate(0,0) scale(1.015)';this.burst=0;}
}
class TunnelLock {
 constructor(){this.found=false;this.unlocked=false;this.key={x:0,z:0,found:false,group:new THREE.Group()};const mat=material(0xd7bc72,{metalness:.65,roughness:.3,emissive:0x6a4811,emissiveIntensity:.5});const ring=new THREE.Mesh(new THREE.TorusGeometry(.13,.035,8,16),mat);ring.position.y=.12;this.key.group.add(ring);box(.05,.32,.05,mat,0,-.12,0,this.key.group);box(.16,.04,.06,mat,.05,-.23,0,this.key.group);scene.add(this.key.group);
 this.gate=new THREE.Group();this.gate.position.set(0,0,40);scene.add(this.gate);const metal=material(0x575e59,{metalness:.7,roughness:.75});for(const x of [-3,3])pole(.13,3,metal,x,0,this.gate);for(let x=-2.8;x<=2.8;x+=.4)box(.045,2.6,.05,metal,x,1.4,0,this.gate);box(6,.08,.09,metal,0,.15,0,this.gate);box(6,.08,.09,metal,0,2.7,0,this.gate);this.gate.name='tunnel-lock-gate';this.lock=box(.22,.3,.13,mat,0,1.25,.1,this.gate);
 }
 reset(point){this.found=false;this.unlocked=false;Object.assign(this.key,point,{found:false});this.key.group.position.set(point.x,.35,point.z);this.key.group.visible=true;this.gate.visible=true;this.lock.visible=true;}
 take(){this.found=true;this.key.found=true;this.key.group.visible=false;audio.pickup();toast('封鎖の鍵を手に入れた。入口で解錠しよう。',4);updateHUD();}
 unlock(){if(!this.found){toast('入口は施錠されている。封鎖の鍵が必要だ。',4);return;}if(this.unlocked)return;this.unlocked=true;this.gate.visible=false;audio.tone(180,.3,.12,'triangle',90);toast('入口の封鎖を解いた。バイクへ戻ろう。',4);updateHUD();}
 canEscape(){return partsFound===7&&this.unlocked;}
}
let seven=null;
const beforeGateCollision=collision;
collision=function(x,z,r=.42){if(seven&&!seven.lock.unlocked&&Math.abs(x)<3+r&&Math.abs(z-40)<.12+r)return true;return beforeGateCollision(x,z,r);};
const sevenBase={init,startGame,updateEnemy,getInteraction,interact,endGame,pauseGame,openModal,returnHome,updateHUD};

init=async function(){await sevenBase.init();if(!ready)return;for(const [name,i]of [['ヒューズ',0],['駆動ベルト',1],['工具セット',2]]){const g=new THREE.Group(),mat=material(0xabbba0,{emissive:0x627852,emissiveIntensity:.65,metalness:.4});if(i===1){const ring=new THREE.Mesh(new THREE.TorusGeometry(.23,.045,8,20),mat);ring.rotation.x=Math.PI/2;g.add(ring);}else{box(i===0?.18:.6,.2,.3,mat,0,0,0,g);}scene.add(g);parts.push({name,x:0,z:0,group:g,found:false});}parts[3].name='燃料ホース';const hose=new THREE.Mesh(new THREE.TorusGeometry(.21,.055,8,20),material(0x82917a,{emissive:0x405438}));parts[3].group.clear();parts[3].group.add(hose);
 seven={lock:new TunnelLock(),static:new ProximityStatic()};
 $('load-message').textContent='7 PARTS + GATE KEY · OFFLINE READY';};
startGame=function(){if(!ready||!seven)return;classicBase.startGame();const layout=classic.spawns.layout(),used=[...layout.items,...layout.cells];const candidates=classic.spawns.shuffle(classic.spawns.reachable.filter(p=>Math.abs(p.x)<37&&Math.abs(p.z)<37&&!collision(p.x,p.z,.7)&&Math.hypot(p.x,p.z-26)>12));const extra=[];for(const p of candidates){if(used.every(q=>Math.hypot(p.x-q.x,p.z-q.z)>4)){extra.push(p);used.push(p);if(extra.length===4)break;}}if(extra.length!==4){state='home';show('fatal');$('fatal-detail').textContent='安全な配置地点を確保できませんでした。再読み込みしてください。';return;}const points=[...layout.items,...extra.slice(0,3)];parts.forEach((p,i)=>{Object.assign(p,points[i]);p.group.position.set(p.x,.42,p.z);});classic.battery.reset();classic.battery.place(layout.cells);seven.lock.reset(extra[3]);Object.assign(enemy,classic.spawns.enemySpawn(points));classic.faces.select();classic.battery.update(0);seven.static.clear();updateHUD();toast('帰路でバイクが故障した。7つの部品と、入口の封鎖の鍵を探そう。',7);};
getInteraction=function(){if(seven){const lock=seven.lock;if(!lock.found&&lock.key.group.visible&&Math.hypot(player.x-lock.key.x,player.z-lock.key.z)<2.6&&clearLine(player.x,player.z,lock.key.x,lock.key.z))return {type:'gate-key'};if(Math.hypot(player.x,player.z-38.5)<3&&!lock.unlocked)return {type:'gate'};}return sevenBase.getInteraction();};
interact=function(){if(state!=='playing')return;const hit=getInteraction();if(hit?.type==='gate-key'){seven.lock.take();return;}if(hit?.type==='gate'){seven.lock.unlock();return;}if(hit?.type==='bike'){if(partsFound<7)toast('修理には、あと'+(7-partsFound)+'つの部品が必要。',3);else if(!seven.lock.unlocked)toast(seven.lock.found?'部品は揃った。トンネル前で鍵を使い、封鎖を解こう。':'部品は揃ったが入口は施錠されている。封鎖の鍵を探そう。',4);else endGame(true);return;}sevenBase.interact();};
const sevenUpdatePlayer=updatePlayer;
updatePlayer=function(dt){sevenUpdatePlayer(dt);const hit=getInteraction();if(hit?.type==='gate-key')$('interaction').textContent='封鎖の鍵を拾う';if(hit?.type==='gate')$('interaction').textContent=seven.lock.found?'鍵で封鎖を解く':'封鎖を調べる';};
updateEnemy=function(dt){const danger=sevenBase.updateEnemy(dt)||0;seven?.static.update(danger);return danger;};
updateHUD=function(){sevenBase.updateHUD();if(!seven)return;$('key-status').textContent=seven.lock.unlocked?'GATE OPEN':seven.lock.found?'KEY FOUND · GATE LOCKED':'KEY — · GATE LOCKED';$('mission-hint').textContent=partsFound<7?'部品 '+partsFound+'/7 と封鎖の鍵を探す':!seven.lock.unlocked?'トンネル前で鍵を使おう':'バイクに戻って脱出';};
endGame=function(won){if(won&&!seven?.lock.canEscape())return;seven?.static.clear();sevenBase.endGame(won);};
pauseGame=function(){seven?.static.clear();sevenBase.pauseGame();};openModal=function(id){seven?.static.clear();sevenBase.openModal(id);};returnHome=function(){seven?.static.clear();sevenBase.returnHome();};


