function inBoundary(x,z,points,r){let inside=false;for(let i=0,j=points.length-1;i<points.length;j=i++){const a=points[i],b=points[j];if(r>0&&x>Math.min(a[0],b[0])-r&&x<Math.max(a[0],b[0])+r&&z>Math.min(a[1],b[1])-r&&z<Math.max(a[1],b[1])+r&&segmentDistance(x,z,...a,...b)<r)return false;if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}

function segmentDistance(x,z,ax,az,bx,bz){const dx=bx-ax,dz=bz-az,t=clamp(((x-ax)*dx+(z-az)*dz)/(dx*dx+dz*dz||1),0,1);return Math.hypot(x-ax-dx*t,z-az-dz*t);}
