 const p=[],t=[];for(let x=-100;x<-44;x+=2)for(let z=-32;z<23;z+=2){for(const [xx,zz]of [[x,z],[x+2,z],[x+2,z+2],[x,z],[x+2,z+2],[x,z+2]]){p.push(xx,this.floor(xx,zz)-.03,zz);t.push(xx*.35,zz*.35);}}this.makeSurface(p,t,mat).name='cave-floor';const ceiling=p.map((v,i)=>i%3===1?v+3.8:v);const roof=this.makeSurface(ceiling,t,mat);roof.name='cave-ceiling';const rp=roof.geometry.attributes.position;const ri=[];for(let i=0;i<rp.count;i+=3)if((rp.getX(i)+rp.getX(i+1)+rp.getX(i+2))/3<-55)ri.push(i,i+1,i+2);roof.geometry.setIndex(ri);this.buildCaveEntrance();
