const revisionInteraction=getInteraction;
getInteraction=function(){return revision?.hit()||revisionInteraction();};
const revisionInteract=interact;
interact=function(){if(state!=='playing')return;const h=revision?.hit();if(h){revision.interact(h);return;}revisionInteract();};
