updatePlayer=function(dt){revisionPlayer(dt);if(!revision||state!=='playing')return;revision.update(dt);const h=revision.hit();if(h){show('interaction');$('interaction').textContent=h.type==='shrine-dial'?'ダイヤル錠を入力':h.type==='shrine-note'?'落ちている紙を読む':h.r.broken?'壊れたラジオを調べる':h.r.on?'ラジオをOFFにする':'ラジオをONにする';}};
const revisionHUD=updateHUD;
updateHUD=function(){revisionHUD();if(revision)$('mission-hint').textContent+=(revision.unlocked?' · 神社：解錠済み':revision.noteFound?' · 神社の番号：'+revision.code:' · 洞窟で神社の番号を探す');};
const revisionAudio=audio.update.bind(audio);audio.update=function(){revisionAudio();revision?.syncAudio();};
for(const name of ['pauseGame','returnHome']){const previous=name==='pauseGame'?pauseGame:returnHome;const wrap=function(){revision?.stopAudio();if(revision)hide('shrine-dialog');previous();};if(name==='pauseGame')pauseGame=wrap;else returnHome=wrap;}
