GameManager.prototype.escape=function(dt){this.exitTime+=dt;const t=clamp(this.exitTime/12,0,1),z=36+22*this.exitTime*this.exitTime/12;camera.position.set(0,2.7+Math.sin(this.exitTime*22)*.018,z);camera.rotation.set(0,Math.PI,0);bike.position.set(0,1.05,z+.15);bike.rotation.y=Math.PI;bike.visible=true;flash.visible=true;flash.position.copy(camera.position);flashTarget.position.set(0,1.2,z+18);scene.fog.density=.026*(1-clamp((z-49)/18,0,1))+.003*clamp((z-49)/18,0,1);scene.fog.color.set(0x142333);scene.background.set(0x101c30);hemi.intensity=.7;moon.intensity=.7;if(Math.floor(this.exitTime*5)!==Math.floor((this.exitTime-dt)*5))audio.tone(48+Math.min(40,this.exitTime*4),.26,.1,'sawtooth');$('escape-fade').style.opacity=String(clamp((t-.87)/.13,0,1));if(t>=1){state='playing';worldBase.endGame(true);$('escape-fade').style.opacity='0';bike.position.set(0,this.map.floor(0,36),36);revision.road.visible=false;}};

let graphicsLost=false;
$('world').addEventListener('webglcontextlost',e=>{e.preventDefault();graphicsLost=true;if(state==='playing')pauseGame();revision?.stopAudio();toast('描画を復旧しています。少しお待ちください。',12);});
$('world').addEventListener('webglcontextrestored',()=>{graphicsLost=false;settings.quality='low';applySettings();toast('描画を復旧しました。「再開」から続けられます。',8);});
const stabilityResume=resumeGame;resumeGame=function(){if(graphicsLost)return;stabilityResume();};

// Touch movement and view use distinct pointer IDs: simultaneous look + run + move.
$('world').addEventListener('pointerdown',e=>{if(state!=='playing')return;e.preventDefault();try{$('world').setPointerCapture(e.pointerId);}catch(_){}if(Math.hypot(e.clientX-($('joystick').getBoundingClientRect().left+50),e.clientY-($('joystick').getBoundingClientRect().top+50))<95&&input.moveId===null){input.moveId=e.pointerId;const pad=$('joystick').getBoundingClientRect();input.originX=pad.left+50;input.originY=pad.top+50;input.mx=input.my=0;const j=$('joystick');j.style.display='block';updateMovePad(e.clientX-input.originX,e.clientY-input.originY);}else if(input.lookId===null){input.lookId=e.pointerId;input.lx=e.clientX;input.ly=e.clientY;}});
$('world').addEventListener('pointermove',e=>{if(state!=='playing')return;if(e.pointerId===input.moveId){updateMovePad(e.clientX-input.originX,e.clientY-input.originY);}if(e.pointerId===input.lookId){const scale=settings.sensitivity/75*.003;yaw-=(e.clientX-input.lx)*scale;pitch=clamp(pitch-(e.clientY-input.ly)*scale,-1.15,1.15);input.lx=e.clientX;input.ly=e.clientY;}});
function releasePointer(e){if(e.pointerId===input.moveId){input.moveId=null;input.mx=input.my=0;runHeld=false;$('joystick').classList.remove('sprinting');$('joystick').style.display='block';$('stick').style.transform='none';}if(e.pointerId===input.lookId)input.lookId=null;}
for(const type of ['pointerup','pointercancel','lostpointercapture'])$('world').addEventListener(type,releasePointer);
// Catch releases even when Safari retargets them outside the canvas.
for(const type of ['pointerup','pointercancel'])window.addEventListener(type,releasePointer,true);
// Touch-end is a fallback for interrupted iOS pointer streams. Do not reset
// while another finger is still moving or controlling the camera.
for(const type of ['touchend','touchcancel'])window.addEventListener(type,e=>{
 if(e.touches.length===0)resetInput();
},{capture:true,passive:true});
window.addEventListener('pagehide',resetInput);
window.addEventListener('orientationchange',resetInput);
document.addEventListener('visibilitychange',()=>{if(document.hidden)resetInput();});
document.addEventListener('selectstart',e=>{
 if(!e.target.closest?.('input,textarea,[contenteditable="true"]'))e.preventDefault();
});
$('world').addEventListener('touchstart',e=>{
 if(state==='playing'&&e.cancelable)e.preventDefault();
},{passive:false});

$('run').addEventListener('pointerdown',e=>{if(state!=='playing')return;e.preventDefault();$('run').setPointerCapture(e.pointerId);runHeld=true;$('run').classList.add('active');});for(const type of ['pointerup','pointercancel','lostpointercapture'])$('run').addEventListener(type,()=>{runHeld=false;$('run').classList.remove('active');});
window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;if(e.code==='Tab'){const modal=document.querySelector('.modal-shade:not(.hidden)');if(modal){const focusable=[...modal.querySelectorAll('button,input,select,a')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus();}}return;}if(e.code==='Escape'||e.code==='KeyP'){if(e.repeat)return;const modal=document.querySelector('#help-modal:not(.hidden),#settings-modal:not(.hidden)');if(modal)closeModal(modal.id);else if(state==='playing')pauseGame();else if(state==='paused')resumeGame();return;}if(state!=='playing')return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(!e.repeat&&e.code==='KeyE')interact();if(!e.repeat&&e.code==='KeyF')toggleLight();});window.addEventListener('keyup',e=>{keys[e.code]=false;});window.addEventListener('blur',()=>{if(state==='playing')pauseGame();resetInput();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pauseGame();});document.addEventListener('contextmenu',e=>e.preventDefault());
for(const id of ['retry','replay'])$(id).addEventListener('click',startGame);for(const id of ['to-title','death-title','win-title'])$(id).addEventListener('click',returnHome);$('pause').onclick=pauseGame;$('resume').onclick=resumeGame;$('interaction').onclick=e=>{if(e.detail===0)interact();};$('light').onclick=toggleLight;$('settings-open').onclick=()=>openModal('settings-modal');$('pause-settings').onclick=()=>openModal('settings-modal');$('help-open').onclick=()=>openModal('help-modal');$('hud-help').onclick=()=>openModal('help-modal');for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>closeModal(b.dataset.close);
